    Returns whether the given integer is prime or not
    """
    # Check if the number is 0, 1, or 2
    if n <= 2:
        return False
    # Check if the number is divisible by any integer from 2 to n-1
    for i in range(2, n):
        if n % i == 0:
            return False
    return True

